<body class="flex flexcol h[100dvh]">

    <! Háttér Animáció >
    <div class="ambientlight">
        <div class="blob blob1"></div>
        <div class="blob blob2"></div>
        <div class="blob blob3"></div>
    </div>

    <! 1. Fejléc (White Glass) >
    <header class="fixed top0 wfull z20 pt2 px2">
        <div class="glass roundedfull px4 h14 flex itemscenter justifybetween mxauto maxw3xl">
            <div class="flex itemscenter gap3">
                <! Ikon háttér: Neon Lime Gradient >
                <div class="w8 h8 roundedfull bggradienttobr from[ccff00] to[ffee00] flex itemscenter justifycenter textblack shadowmd">
                    <i datalucide="zap" class="w4 h4"></i>
                </div>
                <span class="textbase fontmedium trackingwide textblack/80">TiffyTime</span>
            </div>

            <button class="w9 h9 roundedfull hover:bgblack/5 flex itemscenter justifycenter transition textblack/60">
                <i datalucide="menu" class="w5 h5"></i>
            </button>
        </div>
    </header>

    <! 2. Chat Tartalom >
    <main id="chatstream" class="flex1 overflowyauto pt24 pb28 px4 spacey6 noscrollbar md:maxw2xl md:mxauto wfull">

        <! Üres állapot >
        <div id="welcomestate" class="flex flexcol itemscenter justifycenter mt[15vh] opacity100 transitionall duration700">
            <! Lebegő ikon >
            <div class="w20 h20 roundedfull glass flex itemscenter justifycenter mb6 animatefloat shadowxl shadowyellow400/20 border borderwhite">
                <i datalucide="sun" class="w8 h8 textblack/70"></i>
            </div>

            <h1 class="text3xl fontlight textcenter mb2 textblack dropshadowsm">Jó reggelt.</h1>
            <p class="textblack/50 textbase fontlight textcenter maxwxs">
                Milyen friss ötletekre vágysz ma?
            </p>

            <! Javaslat buborékok (Chips) >
            <div class="flex flexwrap justifycenter gap2 mt8">
                <button onclick="app.prefill('Energiát kérek')" class="px5 py2.5 chip roundedfull textsm fontmedium">Energiát kérek ⚡</button>
                <button onclick="app.prefill('Napi terv')" class="px5 py2.5 chip roundedfull textsm fontmedium">Napi terv 📅</button>
                <button onclick="app.prefill('Ötletelés')" class="px5 py2.5 chip roundedfull textsm fontmedium">Ötletelés 💡</button>
            </div>
        </div>

        <div id="messages" class="flex flexcol gap4">
            <! Chat üzenetek >
        </div>

    </main>

    <! 3. Input Sáv (White Glass Capsule) >
    <footer class="fixed bottom0 left0 right0 p4 pb6 z20 flex justifycenter bggradienttot fromwhite/40 totransparent">
        <div class="wfull md:maxw2xl glassstrong rounded[28px] p1.5 flex itemsend gap2 shadowxl shadowblack/5">

            <button onclick="app.toggleMenu()" class="p3 textblack/50 hover:textblack transition roundedfull hover:bgblack/5">
                <i datalucide="plus" class="w6 h6"></i>
            </button>

            <div class="flex1 py3">
                <textarea id="userinput" rows="1" class="wfull bgtransparent textblack text[16px] placeholderblack/30 resizenone maxh32 leadingrelaxed" placeholder="Írj valamit..."></textarea>
            </div>

            <! Küldés gomb: Fekete, hogy üssön a neonon/fehéren >
            <button id="sendbtn" class="p3 bg[1a1a1a] text[ccff00] roundedfull hover:scale105 transition shadowlg disabled:opacity50 disabled:cursornotallowed transform active:scale95" disabled>
                <i datalucide="arrowup" class="w5 h5"></i>
            </button>
        </div>
    </footer>

    <! Script >
    <script>
        const els = {
            input: document.getElementById('userinput'),
            sendBtn: document.getElementById('sendbtn'),
            messages: document.getElementById('messages'),
            welcome: document.getElementById('welcomestate'),
            chatStream: document.getElementById('chatstream')
        };

        const app = {
            init() {
                els.input.addEventListener('input', (e) => {
                    // Autoresize
                    e.target.style.height = 'auto';
                    e.target.style.height = Math.min(e.target.scrollHeight, 120) + 'px';
                    els.sendBtn.disabled = e.target.value.trim() === '';
                });

                els.sendBtn.addEventListener('click', () => this.sendMessage());

                // Enter küldés
                els.input.addEventListener('keydown', (e) => {
                    if (e.key === 'Enter' && !e.shiftKey) {
                        e.preventDefault();
                        if(!els.sendBtn.disabled) this.sendMessage();
                    }
                });

                lucide.createIcons();
            },

            prefill(text) {
                els.input.value = text;
                els.input.focus();
                els.sendBtn.disabled = false;
                this.sendMessage();
            },

            async sendMessage() {
                const text = els.input.value.trim();
                if(!text) return;

                // UI Reset
                els.input.value = '';
                els.input.style.height = 'auto';
                els.sendBtn.disabled = true;

                // Üdvözlő képernyő eltüntetése
                if(els.welcome) {
                    els.welcome.style.opacity = '0';
                    setTimeout(() => els.welcome.remove(), 500);
                }

                // User üzenet
                this.addMessage(text, 'user');

                // AI "gondolkodik"
                this.showTyping();

                // Fake delay
                await new Promise(r => setTimeout(r, 1200));

                this.removeTyping();

                // AI válasz (Demo tartalom)
                const responses = [
                    "Rendben, jegyeztem! Ez a neoncitrus kombináció igazán energikus.",
                    "Szuper ötlet. A tiszta fehér háttér remekül kiemeli a színeket.",
                    "Hozzáadtam a listához. Miben segíthetek még?"
                ];
                const randomResponse = responses[Math.floor(Math.random()  responses.length)];

                this.addMessage(randomResponse, 'ai');
            },

            addMessage(content, role) {
                const div = document.createElement('div');
                div.className = flex w-full fade-in ${role === 'user' ? 'justify-end' : 'justify-start'};

                const bubbleClass = role === 'user' ? 'glassbubbleuser' : 'glassbubbleai';

                div.innerHTML = 
                    <div class="${bubbleClass} px5 py3 maxw[85%] text[16px] leadingrelaxed shadowsm">
                        ${content}
                    </div>
                ;

                els.messages.appendChild(div);
                this.scrollToBottom();
            },

            showTyping() {
                const div = document.createElement('div');
                div.id = 'typingindicator';
                div.className = "flex justifystart fadein ml2";
                div.innerHTML = 
                    <div class="glassbubbleai px4 py3 rounded2xl flex gap1.5 itemscenter h10">
                        <div class="w1.5 h1.5 bgblack/30 roundedfull animatebounce"></div>
                        <div class="w1.5 h1.5 bgblack/30 roundedfull animatebounce" style="animationdelay:0.2s"></div>
                        <div class="w1.5 h1.5 bgblack/30 roundedfull animatebounce" style="animationdelay:0.4s"></div>
                    </div>;
                els.messages.appendChild(div);
                this.scrollToBottom();
            },

            removeTyping() {
                const el = document.getElementById('typingindicator');
                if(el) el.remove();
            },

            scrollToBottom() {
                els.chatStream.scrollTo({ top: els.chatStream.scrollHeight, behavior: 'smooth' });
            },

            toggleMenu() {
                alert("Menü (Demo)");
            }
        };

        app.init();
    </script>
</body>
</html>

