                        A kliens egy általános { "messages": [...] } kérést küld, és több elterjedt válaszformátumot is megpróbál értelmezni.
                    </div>
                </div>
            </div>
        </div>
    </div>
    <script>
        (() => {
            const STORAGE_KEY = "tiffytime_chat_v1";
            const SETTINGS_KEY = "tiffytime_settings_v1";

            const els = {
                input: document.getElementById("user-input"),
                sendBtn: document.getElementById("send-btn"),
                messages: document.getElementById("messages"),
                welcome: document.getElementById("welcome-state"),
                chatStream: document.getElementById("chat-stream"),
                headerMenuBtn: document.getElementById("header-menu-btn"),
                plusBtn: document.getElementById("plus-btn"),
                sheetOverlay: document.getElementById("sheet-overlay"),
                sheetBackdrop: document.getElementById("sheet-backdrop"),
                sheetClose: document.getElementById("sheet-close"),
                apiEndpoint: document.getElementById("api-endpoint"),
                apiCredentials: document.getElementById("api-credentials"),
                clearChat: document.getElementById("clear-chat"),
                exportChat: document.getElementById("export-chat")
            };

            const state = {
                messages: [],
                pending: false,
                abortController: null,
                settings: {
                    endpoint: "/api/chat",
                    includeCredentials: false
                }
            };

            const utils = {
                safeJsonParse(s) {
                    try { return JSON.parse(s); } catch { return null; }
                },
                nowIso() {
                    return new Date().toISOString();
                },
                clamp(n, min, max) {
                    return Math.max(min, Math.min(max, n));
                },
                downloadJson(filename, obj) {
                    const blob = new Blob([JSON.stringify(obj, null, 2)], { type: "application/json;charset=utf-8" });
                    const url = URL.createObjectURL(blob);
                    const a = document.createElement("a");
                    a.href = url;
                    a.download = filename;
                    document.body.appendChild(a);
                    a.click();
                    a.remove();
                    URL.revokeObjectURL(url);
                },
                isNonEmptyString(v) {
                    return typeof v === "string" && v.trim().length > 0;
                },
                normalizeEndpoint(v) {
                    const s = String(v || "").trim();
                    if (!s) return "/api/chat";
                    return s;
                },
                extractReply(payload) {
                    if (payload == null) return null;
                    if (typeof payload === "string") return payload;
                    if (typeof payload.reply === "string") return payload.reply;
                    if (typeof payload.content === "string") return payload.content;
                    if (payload.message && typeof payload.message.content === "string") return payload.message.content;
                    if (payload.data && typeof payload.data.reply === "string") return payload.data.reply;
                    if (payload.choices && payload.choices[0] && payload.choices[0].message && typeof payload.choices[0].message.content === "string") {
                        return payload.choices[0].message.content;
                    }
                    if (payload.output_text && typeof payload.output_text === "string") return payload.output_text;
                    if (payload.output && Array.isArray(payload.output)) {
                        for (const item of payload.output) {
                            if (item && item.content && Array.isArray(item.content)) {
                                for (const c of item.content) {
                                    if (c && c.type === "output_text" && typeof c.text === "string") return c.text;
                                }
                            }
                        }
                    }
                    return null;
                }
            };

            const persistence = {
                loadSettings() {
                    const raw = localStorage.getItem(SETTINGS_KEY);
                    const parsed = utils.safeJsonParse(raw);
                    if (parsed && typeof parsed === "object") {
                        state.settings.endpoint = utils.normalizeEndpoint(parsed.endpoint);
                        state.settings.includeCredentials = Boolean(parsed.includeCredentials);
                    }
                    els.apiEndpoint.value = state.settings.endpoint;
                    els.apiCredentials.checked = state.settings.includeCredentials;
                },
                saveSettings() {
                    state.settings.endpoint = utils.normalizeEndpoint(els.apiEndpoint.value);
                    state.settings.includeCredentials = Boolean(els.apiCredentials.checked);
                    localStorage.setItem(SETTINGS_KEY, JSON.stringify(state.settings));
                },
                loadMessages() {
                    const raw = localStorage.getItem(STORAGE_KEY);
                    const parsed = utils.safeJsonParse(raw);
                    if (parsed && Array.isArray(parsed)) {
                        state.messages = parsed.filter(m => m && (m.role === "user" || m.role === "assistant") && typeof m.content === "string");
                    } else {
                        state.messages = [];
                    }
                },
                saveMessages() {
                    localStorage.setItem(STORAGE_KEY, JSON.stringify(state.messages));
                }
            };

            const ui = {
                initIcons() {
                    if (window.lucide && typeof window.lucide.createIcons === "function") {
                        window.lucide.createIcons();
                    }
                },
                setPending(isPending) {
                    state.pending = isPending;
                    els.sendBtn.disabled = isPending || els.input.value.trim() === "";
                    els.input.disabled = isPending;
                },
                autoResizeTextarea() {
                    const el = els.input;
                    el.style.height = "auto";
                    const h = utils.clamp(el.scrollHeight, 24, 120);
                    el.style.height = h + "px";
                },
                hideWelcome() {
                    if (!els.welcome) return;
                    els.welcome.style.opacity = "0";
                    const toRemove = els.welcome;
                    setTimeout(() => {
                        if (toRemove && toRemove.parentNode) toRemove.remove();
                    }, 500);
                },
                scrollToBottom(behavior) {
                    els.chatStream.scrollTo({ top: els.chatStream.scrollHeight, behavior: behavior || "smooth" });
                },
                addMessage(role, content) {
                    const wrapper = document.createElement("div");
                    wrapper.className = "flex w-full fade-in " + (role === "user" ? "justify-end" : "justify-start");
                    const bubble = document.createElement("div");
                    bubble.className = (role === "user" ? "glass-bubble-user" : "glass-bubble-ai") + " px-5 py-3 max-w-[85%] text-[16px] leading-relaxed shadow-sm whitespace-pre-wrap break-words";
                    bubble.textContent = content;
                    wrapper.appendChild(bubble);
                    els.messages.appendChild(wrapper);
                    ui.scrollToBottom("smooth");
                },
                renderAllMessages() {
                    els.messages.innerHTML = "";
                    for (const m of state.messages) ui.addMessage(m.role === "assistant" ? "ai" : "user", m.content);
                },
                showTyping() {
                    ui.removeTyping();
                    const div = document.createElement("div");
                    div.id = "typing-indicator";
                    div.className = "flex justify-start fade-in ml-2";
                    div.innerHTML = '<div class="glass-bubble-ai px-4 py-3 rounded-2xl flex gap-1.5 items-center h-10"><div class="w-1.5 h-1.5 bg-black/30 rounded-full animate-bounce"></div><div class="w-1.5 h-1.5 bg-black/30 rounded-full animate-bounce" style="animation-delay:0.2s"></div><div class="w-1.5 h-1.5 bg-black/30 rounded-full animate-bounce" style="animation-delay:0.4s"></div></div>';
                    els.messages.appendChild(div);
                    ui.scrollToBottom("smooth");
                },
                removeTyping() {
                    const el = document.getElementById("typing-indicator");
                    if (el) el.remove();
                },
                openSheet() {
                    persistence.loadSettings();
                    els.sheetOverlay.classList.remove("hidden");
                    els.apiEndpoint.focus();
                    ui.initIcons();
                },
                closeSheet() {
                    persistence.saveSettings();
                    els.sheetOverlay.classList.add("hidden");
                }
            };

            const net = {
                async postChat(messages) {
                    if (!utils.isNonEmptyString(state.settings.endpoint)) throw new Error("Hiányzó API végpont.");
                    const controller = new AbortController();
                    state.abortController = controller;
                    const timeoutId = setTimeout(() => controller.abort(), 45000);
                    try {
                        const res = await fetch(state.settings.endpoint, {
                            method: "POST",
                            headers: { "Content-Type": "application/json" },
                            body: JSON.stringify({ messages }),
                            credentials: state.settings.includeCredentials ? "include" : "same-origin",
                            signal: controller.signal
                        });
                        const ct = res.headers.get("content-type") || "";
                        let payload = null;
                        if (ct.includes("application/json")) payload = await res.json();
                        else payload = await res.text();
                        if (!res.ok) {
                            const detail = typeof payload === "string" ? payload : JSON.stringify(payload);
                            const err = new Error("HTTP " + res.status + " " + res.statusText);
                            err.detail = detail;
                            throw err;
                        }
                        return payload;
                    } finally {
                        clearTimeout(timeoutId);
                        state.abortController = null;
                    }
                }
            };

            const app = {
                async sendMessage(text) {
                    const content = String(text || "").trim();
                    if (!content || state.pending) return;

                    ui.hideWelcome();
                    ui.setPending(true);

                    const userMsg = { role: "user", content, ts: utils.nowIso() };
                    state.messages.push(userMsg);
                    persistence.saveMessages();
                    ui.addMessage("user", content);

                    ui.showTyping();

                    try {
                        const payload = await net.postChat(state.messages.map(m => ({ role: m.role, content: m.content })));
                        const reply = utils.extractReply(payload);
                        if (!utils.isNonEmptyString(reply)) {
                            throw new Error("A válasz nem tartalmaz feldolgozható szöveget.");
                        }
                        const assistantMsg = { role: "assistant", content: reply, ts: utils.nowIso() };
                        state.messages.push(assistantMsg);
                        persistence.saveMessages();
                        ui.removeTyping();
                        ui.addMessage("ai", reply);
                    } catch (e) {
                        ui.removeTyping();
                        const msg = (e && e.name === "AbortError") ? "A kérés időtúllépés miatt megszakadt." : ("Hiba: " + (e && e.message ? e.message : "Ismeretlen hiba."));
                        const detail = e && e.detail ? ("\n" + String(e.detail).slice(0, 2000)) : "";
                        ui.addMessage("ai", msg + detail);
                    } finally {
                        ui.setPending(false);
                        els.input.focus();
                    }
                },
                clear() {
                    if (state.abortController) {
                        try { state.abortController.abort(); } catch {}
                    }
                    state.messages = [];
                    persistence.saveMessages();
                    els.messages.innerHTML = "";
                    if (!document.getElementById("welcome-state")) {
                        location.reload();
                    }
                },
                export() {
                    const snapshot = {
                        exportedAt: utils.nowIso(),
                        settings: { ...state.settings },
                        messages: state.messages.map(m => ({ role: m.role, content: m.content, ts: m.ts }))
                    };
                    utils.downloadJson("tiffytime-chat-export.json", snapshot);
                }
            };

            function wireEvents() {
                els.input.addEventListener("input", () => {
                    ui.autoResizeTextarea();
                    els.sendBtn.disabled = state.pending || els.input.value.trim() === "";
                });

                els.sendBtn.addEventListener("click", async () => {
                    const v = els.input.value;
                    els.input.value = "";
                    ui.autoResizeTextarea();
                    await app.sendMessage(v);
                });

                els.input.addEventListener("keydown", async (e) => {
                    if (e.key === "Enter" && !e.shiftKey) {
                        e.preventDefault();
                        if (state.pending) return;
                        const v = els.input.value;
                        if (!v.trim()) return;
                        els.input.value = "";
                        ui.autoResizeTextarea();
                        await app.sendMessage(v);
                    }
                });

                for (const btn of document.querySelectorAll("button[data-prefill]")) {
                    btn.addEventListener("click", async () => {
                        const t = btn.getAttribute("data-prefill") || "";
                        if (!t.trim()) return;
                        els.input.value = "";
                        ui.autoResizeTextarea();
                        await app.sendMessage(t);
                    });
                }

                els.plusBtn.addEventListener("click", () => ui.openSheet());
                els.headerMenuBtn.addEventListener("click", () => ui.openSheet());
                els.sheetClose.addEventListener("click", () => ui.closeSheet());
                els.sheetBackdrop.addEventListener("click", () => ui.closeSheet());

                els.apiEndpoint.addEventListener("change", () => persistence.saveSettings());
                els.apiCredentials.addEventListener("change", () => persistence.saveSettings());

                els.clearChat.addEventListener("click", () => {
                    app.clear();
                });

                els.exportChat.addEventListener("click", () => {
                    persistence.saveSettings();
                    app.export();
                });

                window.addEventListener("visibilitychange", () => {
                    if (document.visibilityState === "hidden" && state.abortController) {
                        try { state.abortController.abort(); } catch {}
                    }
                });
            }

            function boot() {
                persistence.loadSettings();
                persistence.loadMessages();
                wireEvents();
                ui.autoResizeTextarea();
                if (state.messages.length > 0) {
                    ui.hideWelcome();
                    ui.renderAllMessages();
                    ui.scrollToBottom("auto");
                }
                ui.initIcons();
            }

            if (document.readyState === "loading") {
                document.addEventListener("DOMContentLoaded", boot, { once: true });
            } else {
                boot();
            }
        })();
    </script>
</body>
</html>

