    <script type="speculationrules">
        {
            "prefetch": [
                { "source": "document", "where": { "href_matches": "/*" }, "eagerness": "moderate" }
            ],
            "prerender": [
                { "source": "document", "where": { "selector_matches": "a[data-prerender]" }, "eagerness": "conservative" }
            ]
        }
