                    }
                }
            }
        }
    </script>

    <style>
        :root { color-scheme: light; }
        body {
            background-color: #f9f9f9;
            color: #1a1a1a;
            overflow: hidden;
            font-weight: 400;
        }
        .ambient-light {
            position: fixed;
            inset: 0;
            overflow: hidden;
            z-index: -1;
            background: #ffffff;
        }
        .blob {
            position: absolute;
            border-radius: 50%;
            filter: blur(60px);
            opacity: 0.7;
            animation: blob 20s infinite alternate;
        }
        .blob-1 { background: #ccff00; width: 450px; height: 450px; top: -100px; left: -50px; animation-delay: 0s; }
        .blob-2 { background: #fff01f; width: 520px; height: 520px; top: 30%; right: -160px; animation-delay: -5s; }
        .blob-3 { background: #adff2f; width: 420px; height: 420px; bottom: -60px; left: 10%; animation-delay: -10s; }

        .glass {
            background: rgba(255, 255, 255, 0.45);
            backdrop-filter: blur(20px);
            -webkit-backdrop-filter: blur(20px);
            border: 1px solid rgba(255, 255, 255, 0.8);
            box-shadow: 0 4px 22px rgba(0, 0, 0, 0.05);
        }
        .glass-strong {
            background: rgba(255, 255, 255, 0.7);
            backdrop-filter: blur(26px);
