            border: 1px solid rgba(255, 255, 255, 0.86);
            box-shadow: 0 14px 40px rgba(0,0,0,0.08);
        }
        .bubble-user {
            background: #ccff00;
            color: #1a1a1a;
            border: 1px solid rgba(255, 255, 255, 0.45);
