        .report-content p { margin: 10px 0; color: rgba(0,0,0,0.78); }
        .report-content a { color: rgba(0,0,0,0.85); text-decoration: underline; text-decoration-thickness: 1px; text-underline-offset: 3px; }
        .report-content ul, .report-content ol { margin: 10px 0 10px 20px; color: rgba(0,0,0,0.78); }
        .report-content li { margin: 6px 0; }
        .report-content code { background: rgba(0,0,0,0.05); padding: 2px 6px; border-radius: 8px; }
        .report-content pre { background: rgba(0,0,0,0.05); padding: 12px; border-radius: 16px; overflow: auto; }

        .dragging { opacity: 0.7; transform: scale(0.99); }
        .drag-handle { touch-action: none; cursor: grab; }
        .drag-handle:active { cursor: grabbing; }

        .focus-ring:focus-visible { outline: 2px solid rgba(26,26,26,0.65); outline-offset: 2px; }
    </style>
</head>
<body class="h-[100dvh]">
    <div class="ambient-light" aria-hidden="true">
        <div class="blob blob-1"></div>
        <div class="blob blob-2"></div>
        <div class="blob blob-3"></div>
    </div>

    <div id="app-root" class="h-[100dvh] flex flex-col">
        <div id="view-chat" class="h-[100dvh] flex flex-col">
            <header class="fixed top-0 left-0 right-0 z-30 safe-top">
                <div class="px-3 pt-2">
                    <div class="glass rounded-2xl h-12 flex items-center justify-between px-2 max-w-3xl mx-auto">
                        <button id="btn-menu" type="button" class="w-10 h-10 rounded-xl hover:bg-black/5 flex items-center justify-center text-black/70 focus-ring" aria-label="Menü">
                            <i data-lucide="menu" class="w-5 h-5"></i>
                        </button>
                        <div class="flex-1 text-center px-2">
                            <div id="chat-title" class="text-[15px] font-medium text-black/80 truncate">tiffytime</div>
                        </div>
                        <button id="btn-more" type="button" class="w-10 h-10 rounded-xl hover:bg-black/5 flex items-center justify-center text-black/70 focus-ring" aria-label="További műveletek">
                            <i data-lucide="more-horizontal" class="w-5 h-5"></i>
                        </button>
                    </div>
                </div>
            </header>

            <main id="chat-stream" class="flex-1 overflow-y-auto no-scrollbar pt-20 pb-40 px-4 md:px-0 md:max-w-2xl md:mx-auto w-full">
                <div id="welcome-state" class="flex flex-col items-center justify-center mt-[14vh] transition-opacity duration-500">
                    <div class="w-20 h-20 rounded-full glass flex items-center justify-center mb-6 animate-float shadow-xl shadow-yellow-400/20 border border-white">
                        <i data-lucide="sun" class="w-8 h-8 text-black/70"></i>
                    </div>
                    <h1 class="text-3xl font-light text-center mb-2 text-black drop-shadow-sm">Szia.</h1>
                    <p class="text-black/50 text-base font-light text-center max-w-xs">Írj egy kérdést vagy indíts Deep Research-t.</p>
                    <div class="flex flex-wrap justify-center gap-2 mt-8">
                        <button type="button" data-prefill="Kérlek, készíts rövid napi tervet." class="px-5 py-2.5 chip rounded-full text-sm font-medium focus-ring">Napi terv</button>
                        <button type="button" data-prefill="Adj 10 ötletet egy új termékhez." class="px-5 py-2.5 chip rounded-full text-sm font-medium focus-ring">Ötletelés</button>
                        <button type="button" data-prefill="Deep Research: hasonlíts össze 3 opciót, forrásokkal." class="px-5 py-2.5 chip rounded-full text-sm font-medium focus-ring">Deep Research</button>
                    </div>
                </div>
                <div id="messages" class="flex flex-col gap-4 pb-6"></div>
            </main>

            <div id="mode-bar-wrap" class="fixed left-0 right-0 bottom-[92px] z-30 px-4 md:px-0 md:max-w-2xl md:mx-auto w-full hidden">
