    <script>
        (() => {
            const CFG_KEY = "tiffytime_cfg_v2";
            const UI_KEY = "tiffytime_ui_v2";

            const els = {
                chatTitle: document.getElementById("chat-title"),
                chatStream: document.getElementById("chat-stream"),
                messages: document.getElementById("messages"),
                welcome: document.getElementById("welcome-state"),
                input: document.getElementById("user-input"),
                send: document.getElementById("btn-send"),
                tools: document.getElementById("btn-tools"),
                sources: document.getElementById("btn-sources"),
                files: document.getElementById("btn-files"),
                fileInput: document.getElementById("file-input"),
                attachmentsRow: document.getElementById("attachments-row"),
                modeBarWrap: document.getElementById("mode-bar-wrap"),
                exitMode: document.getElementById("btn-exit-mode"),
                btnMenu: document.getElementById("btn-menu"),
                btnMore: document.getElementById("btn-more"),

                viewChat: document.getElementById("view-chat"),
                viewReport: document.getElementById("view-report"),
                reportTitle: document.getElementById("report-title"),
                reportMeta: document.getElementById("report-meta"),
                reportBody: document.getElementById("report-body"),
                reportScroll: document.getElementById("report-scroll"),
                reportBack: document.getElementById("btn-report-back"),
                reportMore: document.getElementById("btn-report-more"),

                sheetTools: document.getElementById("sheet-tools"),
                sheetSources: document.getElementById("sheet-sources"),
                sheetMenu: document.getElementById("sheet-menu"),
                sheetEditPlan: document.getElementById("sheet-edit-plan"),
                sheetSourcesPanel: document.getElementById("sheet-sources-panel"),

                toolDeepResearch: document.getElementById("tool-deep-research"),
                toolNormalChat: document.getElementById("tool-normal-chat"),
                sourcesChips: document.getElementById("sources-chips"),
                sourcesApply: document.getElementById("btn-sources-apply"),

                cfgChatEndpoint: document.getElementById("cfg-chat-endpoint"),
                cfgDrBase: document.getElementById("cfg-dr-base"),
                cfgCredentials: document.getElementById("cfg-credentials"),
                btnExport: document.getElementById("btn-export"),
                btnClear: document.getElementById("btn-clear"),
                btnNewChat: document.getElementById("btn-new-chat"),
                recentList: document.getElementById("recent-list"),

                btnNotifyEnable: document.getElementById("btn-notify-enable"),
                btnNotifyTest: document.getElementById("btn-notify-test"),
                notifyStatus: document.getElementById("notify-status"),

                planEditorList: document.getElementById("plan-editor-list"),
                btnPlanAdd: document.getElementById("btn-plan-add"),
                btnPlanCancel: document.getElementById("btn-plan-cancel"),
                btnPlanSave: document.getElementById("btn-plan-save"),

                reportSourcesList: document.getElementById("report-sources-list")
            };

            const state = {
                cfg: {
                    chatEndpoint: "/api/chat",
                    drBase: "/api/deep-research",
                    credentials: false
                },
                ui: {
                    deepResearchMode: false,
                    sources: ["web"]
                },
                currentConversationId: null,
                currentReport: null,
                attachments: [],
                pending: false,
                abort: null,
                planEditor: {
                    messageId: null,
                    original: null,
                    draft: null
                }
            };

            const uid = () => {
                if (crypto && crypto.randomUUID) return crypto.randomUUID();
                const buf = new Uint8Array(16);
                crypto.getRandomValues(buf);
                const hex = [...buf].map(b => b.toString(16).padStart(2, "0")).join("");
                return hex.slice(0, 8) + "-" + hex.slice(8, 12) + "-" + hex.slice(12, 16) + "-" + hex.slice(16, 20) + "-" + hex.slice(20);
            };

            const nowIso = () => new Date().toISOString();

            const clamp = (n, min, max) => Math.max(min, Math.min(max, n));

            const safeJsonParse = (s) => {
                try { return JSON.parse(s); } catch { return null; }
            };

            const isNonEmpty = (v) => typeof v === "string" && v.trim().length > 0;

            const escapeFileName = (name) => String(name || "export.json").replace(/[^\w.\-]+/g, "_");

            const downloadJson = (filename, obj) => {
                const blob = new Blob([JSON.stringify(obj, null, 2)], { type: "application/json;charset=utf-8" });
                const url = URL.createObjectURL(blob);
                const a = document.createElement("a");
                a.href = url;
                a.download = escapeFileName(filename);
                document.body.appendChild(a);
                a.click();
                a.remove();
                URL.revokeObjectURL(url);
            };

            const idb = (() => {
                const DB_NAME = "tiffytime_db_v2";
                const DB_VER = 1;
                let dbp = null;

                const open = () => {
                    if (dbp) return dbp;
                    dbp = new Promise((resolve, reject) => {
                        const req = indexedDB.open(DB_NAME, DB_VER);
                        req.onupgradeneeded = () => {
                            const db = req.result;
                            if (!db.objectStoreNames.contains("conversations")) {
                                db.createObjectStore("conversations", { keyPath: "id" });
                            }
                        };
                        req.onsuccess = () => resolve(req.result);
                        req.onerror = () => reject(req.error || new Error("IndexedDB open error"));
                    });
                    return dbp;
                };

                const tx = async (mode) => {
                    const db = await open();
                    return db.transaction(["conversations"], mode).objectStore("conversations");
                };

                const get = async (id) => {
                    const store = await tx("readonly");
                    return await new Promise((resolve, reject) => {
                        const req = store.get(id);
                        req.onsuccess = () => resolve(req.result || null);
                        req.onerror = () => reject(req.error || new Error("IndexedDB get error"));
                    });
                };

                const put = async (doc) => {
                    const store = await tx("readwrite");
                    return await new Promise((resolve, reject) => {
                        const req = store.put(doc);
                        req.onsuccess = () => resolve(true);
                        req.onerror = () => reject(req.error || new Error("IndexedDB put error"));
                    });
                };

                const del = async (id) => {
                    const store = await tx("readwrite");
                    return await new Promise((resolve, reject) => {
                        const req = store.delete(id);
                        req.onsuccess = () => resolve(true);
                        req.onerror = () => reject(req.error || new Error("IndexedDB delete error"));
                    });
                };

                const list = async () => {
                    const store = await tx("readonly");
                    return await new Promise((resolve, reject) => {
                        const req = store.getAll();
                        req.onsuccess = () => resolve(Array.isArray(req.result) ? req.result : []);
                        req.onerror = () => reject(req.error || new Error("IndexedDB getAll error"));
                    });
                };

                return { get, put, del, list };
            })();

            const cfg = {
                load() {
                    const raw = localStorage.getItem(CFG_KEY);
                    const parsed = safeJsonParse(raw);
                    if (parsed && typeof parsed === "object") {
                        if (isNonEmpty(parsed.chatEndpoint)) state.cfg.chatEndpoint = String(parsed.chatEndpoint);
                        if (isNonEmpty(parsed.drBase)) state.cfg.drBase = String(parsed.drBase);
                        state.cfg.credentials = Boolean(parsed.credentials);
                    }
                    els.cfgChatEndpoint.value = state.cfg.chatEndpoint;
                    els.cfgDrBase.value = state.cfg.drBase;
                    els.cfgCredentials.checked = state.cfg.credentials;
                },
                save() {
                    state.cfg.chatEndpoint = String(els.cfgChatEndpoint.value || "").trim() || "/api/chat";
                    state.cfg.drBase = String(els.cfgDrBase.value || "").trim() || "/api/deep-research";
                    state.cfg.credentials = Boolean(els.cfgCredentials.checked);
                    localStorage.setItem(CFG_KEY, JSON.stringify(state.cfg));
                }
            };

            const uiState = {
                load() {
                    const raw = localStorage.getItem(UI_KEY);
                    const parsed = safeJsonParse(raw);
                    if (parsed && typeof parsed === "object") {
                        state.ui.deepResearchMode = Boolean(parsed.deepResearchMode);
                        if (Array.isArray(parsed.sources) && parsed.sources.length) {
                            state.ui.sources = parsed.sources.map(String).filter(Boolean);
                        }
                    }
                    uiState.applyModeBar();
                },
                save() {
                    localStorage.setItem(UI_KEY, JSON.stringify({
                        deepResearchMode: state.ui.deepResearchMode,
                        sources: state.ui.sources
                    }));
                },
                applyModeBar() {
                    els.modeBarWrap.classList.toggle("hidden", !state.ui.deepResearchMode);
                }
            };

            const sheets = {
                open(id) {
                    const el = document.getElementById(id);
                    if (!el) return;
                    el.classList.remove("sheet-hidden");
                    if (window.lucide && typeof window.lucide.createIcons === "function") window.lucide.createIcons();
                },
                close(id) {
                    const el = document.getElementById(id);
                    if (!el) return;
                    el.classList.add("sheet-hidden");
                }
            };

            const net = {
                async fetchJson(url, options) {
                    const controller = new AbortController();
                    state.abort = controller;
                    const timeoutId = setTimeout(() => controller.abort(), 60000);
                    try {
                        const res = await fetch(url, { ...options, signal: controller.signal });
                        const ct = res.headers.get("content-type") || "";
                        let payload;
                        if (ct.includes("application/json")) payload = await res.json();
                        else payload = await res.text();
                        if (!res.ok) {
                            const err = new Error("HTTP " + res.status + " " + res.statusText);
                            err.payload = payload;
                            throw err;
                        }
                        return payload;
                    } finally {
                        clearTimeout(timeoutId);
                        state.abort = null;
                    }
                },
                async postJson(url, body) {
                    return await net.fetchJson(url, {
                        method: "POST",
                        headers: { "Content-Type": "application/json" },
                        body: JSON.stringify(body),
                        credentials: state.cfg.credentials ? "include" : "same-origin"
                    });
                },
                async postForm(url, formData) {
