            const deepResearch = {
                base(path) {
                    const base = String(state.cfg.drBase || "").trim() || "/api/deep-research";
                    const p = String(path || "");
                    if (base.endsWith("/") && p.startsWith("/")) return base.slice(0, -1) + p;
                    if (!base.endsWith("/") && !p.startsWith("/")) return base + "/" + p;
                    return base + p;
                },
                async createPlan(conversation, query) {
                    const payload = await net.postJson(deepResearch.base("/plan"), {
                        conversationId: conversation.id,
                        query: String(query),
                        sources: state.ui.sources
                    });
                    const plan = payload && Array.isArray(payload.plan) ? payload.plan.map(x => String(x)) : null;
                    const title = payload && payload.title ? String(payload.title) : null;
                    const id = payload && payload.planId ? String(payload.planId) : uid();
                    if (!plan || !plan.length) {
                        const err = new Error("A /plan válasz nem tartalmaz plan tömböt.");
                        err.payload = payload;
                        throw err;
                    }
                    return { planId: id, title, plan, raw: payload };
                },
                async startRun(conversation, planMessage) {
                    const payload = await net.postJson(deepResearch.base("/start"), {
                        conversationId: conversation.id,
                        query: String(planMessage.query || ""),
                        planId: String(planMessage.planId || ""),
                        plan: Array.isArray(planMessage.plan) ? planMessage.plan : [],
                        sources: Array.isArray(planMessage.sources) ? planMessage.sources : state.ui.sources
                    });
                    const runId = payload && payload.runId ? String(payload.runId) : null;
                    const title = payload && payload.title ? String(payload.title) : (conversation.title || "Report");
                    if (!runId) {
                        const err = new Error("A /start válasz nem tartalmaz runId-t.");
                        err.payload = payload;
                        throw err;
                    }
                    return { runId, title, raw: payload };
                },
                async fetchReport(conversationId, runId) {
                    const payload = await net.postJson(deepResearch.base("/report"), { conversationId, runId });
                    const markdown = payload && (payload.markdown || payload.report || payload.content) ? String(payload.markdown || payload.report || payload.content) : "";
                    const title = payload && payload.title ? String(payload.title) : "Report";
                    const sources = payload && Array.isArray(payload.sources) ? payload.sources : [];
                    if (!markdown) {
                        const err = new Error("A /report válasz nem tartalmaz markdown/content mezőt.");
                        err.payload = payload;
                        throw err;
                    }
                    return { title, markdown, sources, updatedAt: nowIso(), raw: payload };
                },
                async fetchStatus(conversationId, runId) {
                    const payload = await net.postJson(deepResearch.base("/status"), { conversationId, runId });
                    return payload;
                },
                startMonitoring(conversation, runId, progressMessageId) {
                    const supportsSse = "EventSource" in window;
                    const monitor = { stop: false, es: null, timer: null };

                    const onStep = async (stepText, progress) => {
                        const doc = await model.loadConversation(conversation.id);
                        if (!doc) return;
                        const idx = doc.messages.findIndex(m => m && m.id === progressMessageId);
                        if (idx < 0) return;
                        const msg = doc.messages[idx];
                        if (msg.type !== "dr_progress") return;
                        msg.stream = Array.isArray(msg.stream) ? msg.stream : [];
                        if (stepText) msg.stream.push(String(stepText));
                        if (typeof progress === "number") msg.progress = clamp(progress, 0, 100);
                        await model.saveConversation(doc);
                        await render.renderConversation(doc);
                    };

                    const onDone = async () => {
                        const doc = await model.loadConversation(conversation.id);
                        if (!doc) return;
                        const idx = doc.messages.findIndex(m => m && m.id === progressMessageId);
                        if (idx < 0) return;
                        const pm = doc.messages[idx];
                        const runTitle = pm && pm.title ? String(pm.title) : doc.title;
                        const readyMsg = {
                            id: uid(),
                            type: "dr_ready",
                            runId,
                            title: runTitle,
                            createdAt: nowIso()
                        };
                        doc.messages.push(readyMsg);
                        doc.runs = doc.runs || {};
                        doc.runs[runId] = doc.runs[runId] || {};
                        doc.runs[runId].status = "ready";
                        doc.runs[runId].updatedAt = nowIso();
                        await model.saveConversation(doc);
                        await render.renderConversation(doc);
                        notifications.reportReady(runTitle);
                    };

                    const stop = () => {
                        monitor.stop = true;
                        if (monitor.es) {
                            try { monitor.es.close(); } catch {}
                            monitor.es = null;
                        }
                        if (monitor.timer) {
                            clearInterval(monitor.timer);
                            monitor.timer = null;
                        }
                    };

                    const trySse = () => {
                        const url = deepResearch.base("/events") + "?conversationId=" + encodeURIComponent(conversation.id) + "&runId=" + encodeURIComponent(runId);
                        const es = new EventSource(url, { withCredentials: state.cfg.credentials });
                        monitor.es = es;

                        es.addEventListener("message", async (ev) => {
                            if (monitor.stop) return;
                            const data = safeJsonParse(ev.data);
                            if (!data) return;
                            const type = String(data.type || "");
                            if (type === "step") await onStep(data.text || data.message || "", data.progress);
                            if (type === "progress") await onStep(data.text || "", data.progress);
                            if (type === "done") { stop(); await onDone(); }
                        });

                        es.addEventListener("error", () => {
                            if (monitor.stop) return;
                            try { es.close(); } catch {}
                            monitor.es = null;
                            startPolling();
                        });
                    };

                    const startPolling = () => {
                        if (monitor.timer) return;
                        monitor.timer = setInterval(async () => {
                            if (monitor.stop) return;
                            try {
                                const st = await deepResearch.fetchStatus(conversation.id, runId);
                                const phase = st && st.status ? String(st.status) : "";
                                const progress = (st && typeof st.progress === "number") ? st.progress : null;
                                const last = st && st.lastStep ? String(st.lastStep) : "";
                                if (last || typeof progress === "number") await onStep(last, progress);
                                if (phase === "ready" || phase === "done" || phase === "completed") {
                                    stop();
                                    await onDone();
                                }
                            } catch {}
                        }, 3000);
                    };

                    if (supportsSse) trySse();
                    else startPolling();

                    return { stop };
                }
            };

            const planEditor = {
                open(planMsg) {
                    state.planEditor.messageId = planMsg.id;
                    state.planEditor.original = Array.isArray(planMsg.plan) ? [...planMsg.plan] : [];
                    state.planEditor.draft = Array.isArray(planMsg.plan) ? [...planMsg.plan] : [];
                    planEditor.render();
                    sheets.open("sheet-edit-plan");
                },
                close() {
                    state.planEditor.messageId = null;
                    state.planEditor.original = null;
                    state.planEditor.draft = null;
                    sheets.close("sheet-edit-plan");
                },
                render() {
                    const list = Array.isArray(state.planEditor.draft) ? state.planEditor.draft : [];
                    els.planEditorList.innerHTML = "";
                    for (let i = 0; i < list.length; i++) {
                        const row = document.createElement("div");
                        row.className = "rounded-2xl px-3 py-2 bg-white/60 border border-white/80 flex items-center gap-2";
                        row.dataset.index = String(i);

                        const handle = document.createElement("button");
                        handle.type = "button";
                        handle.className = "drag-handle w-10 h-10 rounded-2xl hover:bg-black/5 flex items-center justify-center text-black/55 focus-ring flex-none";
                        handle.setAttribute("aria-label", "Átrendezés");
                        handle.innerHTML = '<i data-lucide="grip-vertical" class="w-5 h-5"></i>';

                        const input = document.createElement("input");
                        input.className = "flex-1 bg-transparent text-sm text-black/80 focus:outline-none";
                        input.value = String(list[i] || "");
                        input.addEventListener("input", () => {
                            const idx = Number(row.dataset.index);
                            const val = String(input.value || "");
                            state.planEditor.draft[idx] = val;
                        });

                        const del = document.createElement("button");
                        del.type = "button";
                        del.className = "w-10 h-10 rounded-2xl hover:bg-black/5 flex items-center justify-center text-black/55 focus-ring flex-none";
                        del.setAttribute("aria-label", "Törlés");
                        del.innerHTML = '<i data-lucide="trash-2" class="w-5 h-5"></i>';
                        del.addEventListener("click", () => {
                            const idx = Number(row.dataset.index);
                            state.planEditor.draft.splice(idx, 1);
                            planEditor.render();
                        });

                        row.appendChild(handle);
                        row.appendChild(input);
                        row.appendChild(del);
                        els.planEditorList.appendChild(row);
                    }
                    planEditor.enableReorder();
                    if (window.lucide && typeof window.lucide.createIcons === "function") window.lucide.createIcons();
                },
                enableReorder() {
                    let draggingEl = null;
                    let draggingIndex = -1;

                    const pointerMove = (e) => {
                        if (!draggingEl) return;
                        const x = e.clientX;
                        const y = e.clientY;
                        const el = document.elementFromPoint(x, y);
                        if (!el) return;
                        const row = el.closest && el.closest("#plan-editor-list > div");
                        if (!row) return;
                        const overIndex = Number(row.dataset.index);
                        if (Number.isNaN(overIndex) || overIndex === draggingIndex) return;
                        const draft = state.planEditor.draft;
                        const item = draft.splice(draggingIndex, 1)[0];
                        draft.splice(overIndex, 0, item);
                        draggingIndex = overIndex;
                        planEditor.render();
                        draggingEl = els.planEditorList.querySelector('div[data-index="' + overIndex + '"]') || null;
                        if (draggingEl) draggingEl.classList.add("dragging");
                    };

                    const pointerUp = () => {
                        if (!draggingEl) return;
                        draggingEl.classList.remove("dragging");
                        draggingEl = null;
                        draggingIndex = -1;
                        window.removeEventListener("pointermove", pointerMove, true);
                        window.removeEventListener("pointerup", pointerUp, true);
                    };

                    for (const row of els.planEditorList.querySelectorAll(":scope > div")) {
                        const handle = row.querySelector(".drag-handle");
                        if (!handle) continue;
                        handle.addEventListener("pointerdown", (e) => {
                            e.preventDefault();
                            const idx = Number(row.dataset.index);
                            if (Number.isNaN(idx)) return;
                            draggingEl = row;
                            draggingIndex = idx;
                            draggingEl.classList.add("dragging");
                            window.addEventListener("pointermove", pointerMove, true);
                            window.addEventListener("pointerup", pointerUp, true);
                        }, { passive: false });
                    }
                }
            };

            const app = {
                async boot() {
                    cfg.load();
                    uiState.load();
                    chips.renderSources();
                    notifications.updateStatus();

                    let id = null;
                    if (location.hash && location.hash.length > 1) id = decodeURIComponent(location.hash.slice(1));
                    if (!id) {
                        const docs = await model.listConversations();
                        if (docs.length) id = docs[0].id;
                    }
                    let doc = id ? await model.loadConversation(id) : null;
                    if (!doc) doc = await model.newConversation();
                    state.currentConversationId = doc.id;
                    els.chatTitle.textContent = doc.title || "tiffytime";
                    await render.renderConversation(doc);
                    await app.renderRecent();

                    app.wire();
                    render.autoResize();
                    app.refreshSendEnabled();

                    if (window.lucide && typeof window.lucide.createIcons === "function") window.lucide.createIcons();
                },
                wire() {
                    document.addEventListener("click", (e) => {
                        const t = e.target;
                        const closer = t && t.closest ? t.closest("[data-sheet-close]") : null;
                        if (closer) {
                            const id = closer.getAttribute("data-sheet-close");
                            sheets.close(id);
                            cfg.save();
                            return;
                        }
                    });

                    els.input.addEventListener("input", () => {
                        render.autoResize();
                        app.refreshSendEnabled();
                    });

                    els.input.addEventListener("keydown", async (e) => {
                        if (e.key === "Enter" && !e.shiftKey) {
                            e.preventDefault();
                            if (state.pending) return;
                            if (!els.input.value.trim()) return;
                            await app.onSend();
                        }
                    });

                    els.send.addEventListener("click", async () => {
                        if (state.pending) return;
                        await app.onSend();
                    });

                    for (const btn of document.querySelectorAll("button[data-prefill]")) {
                        btn.addEventListener("click", async () => {
                            const text = String(btn.getAttribute("data-prefill") || "");
                            if (!text.trim()) return;
                            els.input.value = text;
                            render.autoResize();
                            app.refreshSendEnabled();
                            await app.onSend();
                        });
                    }

                    els.tools.addEventListener("click", () => sheets.open("sheet-tools"));
                    els.sources.addEventListener("click", () => {
                        chips.renderSources();
                        sheets.open("sheet-sources");
                    });

                    els.sourcesApply.addEventListener("click", () => {
                        if (!state.ui.sources.length) state.ui.sources = ["web"];
                        uiState.save();
                        sheets.close("sheet-sources");
                    });

                    els.toolDeepResearch.addEventListener("click", () => {
                        state.ui.deepResearchMode = true;
                        uiState.save();
                        uiState.applyModeBar();
                        sheets.close("sheet-tools");
                    });

                    els.toolNormalChat.addEventListener("click", () => {
                        state.ui.deepResearchMode = false;
                        uiState.save();
                        uiState.applyModeBar();
                        sheets.close("sheet-tools");
                    });

                    els.exitMode.addEventListener("click", () => {
                        state.ui.deepResearchMode = false;
                        uiState.save();
                        uiState.applyModeBar();
                    });

                    els.files.addEventListener("click", () => {
                        els.fileInput.click();
                    });

                    els.fileInput.addEventListener("change", async () => {
                        const files = Array.from(els.fileInput.files || []);
                        els.fileInput.value = "";
                        if (!files.length) return;
                        for (const f of files) {
                            state.attachments.push({ id: uid(), name: f.name, size: f.size, type: f.type || "application/octet-stream", file: f });
                        }
                        app.renderAttachments();
                        app.refreshSendEnabled();
                    });

                    els.messages.addEventListener("click", async (e) => {
                        const t = e.target;
                        const btn = t && t.closest ? t.closest("button[data-action]") : null;
                        if (!btn) return;
                        const action = btn.dataset.action || "";
                        if (action === "dr-edit-plan") {
                            const messageId = btn.dataset.messageId;
                            await app.openPlanEditor(messageId);
                        }
                        if (action === "dr-start") {
                            const messageId = btn.dataset.messageId;
                            await app.startResearch(messageId);
                        }
                        if (action === "dr-open") {
                            const runId = btn.dataset.runId;
                            await app.openReport(runId);
                        }
                        if (action === "dr-sources") {
                            const runId = btn.dataset.runId;
                            await app.openReportSources(runId);
                        }
                    });

                    els.btnMenu.addEventListener("click", async () => {
                        cfg.load();
                        await app.renderRecent();
                        notifications.updateStatus();
                        sheets.open("sheet-menu");
                    });

                    els.btnMore.addEventListener("click", async () => {
                        cfg.load();
                        await app.renderRecent();
                        notifications.updateStatus();
                        sheets.open("sheet-menu");
                    });

                    els.cfgChatEndpoint.addEventListener("change", () => cfg.save());
                    els.cfgDrBase.addEventListener("change", () => cfg.save());
                    els.cfgCredentials.addEventListener("change", () => cfg.save());

                    els.btnExport.addEventListener("click", async () => {
                        cfg.save();
                        const doc = await model.loadConversation(state.currentConversationId);
                        if (!doc) return;
                        downloadJson("tiffytime-export-" + doc.id + ".json", doc);
                    });

                    els.btnClear.addEventListener("click", async () => {
                        const doc = await model.loadConversation(state.currentConversationId);
                        if (!doc) return;
                        doc.messages = [];
                        doc.runs = {};
                        await model.saveConversation(doc);
                        location.reload();
                    });

                    els.btnNewChat.addEventListener("click", async () => {
                        const doc = await model.newConversation();
                        els.chatTitle.textContent = doc.title || "tiffytime";
                        render.clearMessages();
                        location.reload();
                    });

                    els.btnNotifyEnable.addEventListener("click", async () => {
                        await notifications.enable();
                    });

                    els.btnNotifyTest.addEventListener("click", () => notifications.test());

                    els.reportBack.addEventListener("click", () => reportView.backToChat());

                    els.reportMore.addEventListener("click", () => {
                        if (state.currentReport && Array.isArray(state.currentReport.sources)) {
                            reportView.openSourcesPanel(state.currentReport.sources);
                        } else {
                            reportView.openSourcesPanel([]);
                        }
                    });

                    els.btnPlanCancel.addEventListener("click", () => planEditor.close());

                    els.btnPlanAdd.addEventListener("click", () => {
                        state.planEditor.draft = Array.isArray(state.planEditor.draft) ? state.planEditor.draft : [];
                        state.planEditor.draft.push("");
                        planEditor.render();
                    });

                    els.btnPlanSave.addEventListener("click", async () => {
                        await app.savePlanEdits();
                    });

                    window.addEventListener("hashchange", async () => {
                        const id = location.hash && location.hash.length > 1 ? decodeURIComponent(location.hash.slice(1)) : null;
                        if (!id) return;
                        const doc = await model.loadConversation(id);
                        if (!doc) return;
                        state.currentConversationId = doc.id;
                        els.chatTitle.textContent = doc.title || "tiffytime";
                        await render.renderConversation(doc);
                        await app.renderRecent();
                    });

                    window.addEventListener("visibilitychange", () => {
                        if (document.visibilityState === "hidden" && state.abort) {
                            try { state.abort.abort(); } catch {}
                        }
                    });
                },
                refreshSendEnabled() {
                    const hasText = els.input.value.trim().length > 0;
                    const hasAttach = state.attachments.length > 0;
                    els.send.disabled = state.pending || (!hasText && !hasAttach);
                },
                renderAttachments() {
                    const items = state.attachments;
                    if (!items.length) {
                        els.attachmentsRow.classList.add("hidden");
                        els.attachmentsRow.innerHTML = "";
                        return;
                    }
                    els.attachmentsRow.classList.remove("hidden");
                    els.attachmentsRow.innerHTML = "";
                    for (const a of items) {
                        const chip = document.createElement("div");
                        chip.className = "rounded-full px-3 py-1.5 bg-white/60 border border-white/80 text-xs text-black/70 flex items-center gap-2";
                        const name = document.createElement("div");
                        name.className = "max-w-[170px] truncate";
                        name.textContent = a.name;
                        const x = document.createElement("button");
                        x.type = "button";
                        x.className = "w-6 h-6 rounded-full hover:bg-black/5 flex items-center justify-center text-black/60 focus-ring";
                        x.setAttribute("aria-label", "Eltávolítás");
                        x.innerHTML = '<i data-lucide="x" class="w-4 h-4"></i>';
                        x.addEventListener("click", () => {
                            state.attachments = state.attachments.filter(it => it.id !== a.id);
                            app.renderAttachments();
                            app.refreshSendEnabled();
                            if (window.lucide && typeof window.lucide.createIcons === "function") window.lucide.createIcons();
                        });
                        chip.appendChild(name);
                        chip.appendChild(x);
                        els.attachmentsRow.appendChild(chip);
                    }
                    if (window.lucide && typeof window.lucide.createIcons === "function") window.lucide.createIcons();
                },
                async renderRecent() {
                    const docs = await model.listConversations();
                    els.recentList.innerHTML = "";
                    if (!docs.length) {
                        const empty = document.createElement("div");
                        empty.className = "rounded-2xl px-4 py-3 bg-white/60 border border-white/80 text-sm text-black/65";
                        empty.textContent = "Nincs beszélgetés.";
                        els.recentList.appendChild(empty);
                        return;
                    }
                    for (const d of docs.slice(0, 30)) {
                        const row = document.createElement("button");
                        row.type = "button";
                        row.className = "w-full rounded-2xl px-4 py-3 bg-white/60 border border-white/80 text-left hover:bg-white/80 transition focus-ring";
                        const title = document.createElement("div");
                        title.className = "text-sm font-semibold text-black/80 truncate";
                        title.textContent = d.title || "tiffytime";
                        const sub = document.createElement("div");
                        sub.className = "text-xs text-black/50 mt-1 flex items-center justify-between gap-2";
                        const left = document.createElement("div");
                        left.className = "truncate";
                        left.textContent = d.updatedAt ? String(d.updatedAt) : "";
                        const right = document.createElement("div");
                        right.className = "flex-none";
                        const msgCount = Array.isArray(d.messages) ? d.messages.length : 0;
                        right.textContent = msgCount + " msg";
                        sub.appendChild(left);
                        sub.appendChild(right);
                        row.appendChild(title);
                        row.appendChild(sub);
                        row.addEventListener("click", () => {
                            history.replaceState(null, "", "#" + encodeURIComponent(d.id));
                            sheets.close("sheet-menu");
                            window.dispatchEvent(new HashChangeEvent("hashchange"));
                        });
                        els.recentList.appendChild(row);
                    }
                },
                async onSend() {
                    const text = els.input.value.trim();
                    const attachments = state.attachments.slice();
                    if (!text && !attachments.length) return;
                    render.hideWelcome();
                    render.setPending(true);

                    const doc = await model.loadConversation(state.currentConversationId);
                    if (!doc) {
                        render.setPending(false);
                        return;
                    }

                    els.input.value = "";
                    render.autoResize();
                    state.attachments = [];
                    app.renderAttachments();
                    app.refreshSendEnabled();

                    if (text) {
                        doc.messages.push({ id: uid(), type: "text", role: "user", content: text, createdAt: nowIso() });
                    } else if (attachments.length) {
                        doc.messages.push({ id: uid(), type: "text", role: "user", content: "", createdAt: nowIso() });
                    }

                    await model.saveConversation(doc);
                    await render.renderConversation(doc);

                    try {
                        if (attachments.length) {
                            const uploadInfo = await app.uploadAttachments(doc, attachments);
                            if (uploadInfo && Array.isArray(uploadInfo.attachments)) {
                                const last = doc.messages[doc.messages.length - 1];
                                last.attachments = uploadInfo.attachments;
                                await model.saveConversation(doc);
                            }
                        }

                        if (state.ui.deepResearchMode) {
                            await app.sendDeepResearch(text, doc);
                        } else {
                            await app.sendChat(text, doc);
                        }
                    } catch (e) {
                        const errText = (e && e.name === "AbortError") ? "A kérés időtúllépés miatt megszakadt." : ("Hiba: " + (e && e.message ? e.message : "Ismeretlen hiba"));
                        doc.messages.push({ id: uid(), type: "text", role: "assistant", content: errText, createdAt: nowIso() });
                        await model.saveConversation(doc);
                        await render.renderConversation(doc);
                    } finally {
                        render.setPending(false);
                        els.input.focus();
                    }
                },
                async uploadAttachments(doc, attachments) {
                    const url = (String(state.cfg.chatEndpoint || "").trim() || "/api/chat").replace(/\/+$/, "") + "/attachments";
                    const form = new FormData();
                    form.append("conversationId", doc.id);
                    for (const a of attachments) {
                        if (a && a.file instanceof File) form.append("files", a.file, a.name);
                    }
                    try {
                        const res = await net.postForm(url, form);
                        return res;
                    } catch {
                        return null;
                    }
                },
                async sendChat(text, doc) {
                    const payload = await net.postJson(state.cfg.chatEndpoint, {
                        conversationId: doc.id,
                        messages: doc.messages
                            .filter(m => m && m.type === "text" && (m.role === "user" || m.role === "assistant"))
                            .map(m => ({ role: m.role, content: String(m.content || ""), attachments: m.attachments || undefined }))
                    });

                    const reply =
                        (payload && typeof payload.reply === "string" && payload.reply) ? payload.reply :
                        (payload && typeof payload.content === "string" && payload.content) ? payload.content :
                        (payload && payload.message && typeof payload.message.content === "string") ? payload.message.content :
                        (payload && payload.choices && payload.choices[0] && payload.choices[0].message && typeof payload.choices[0].message.content === "string") ? payload.choices[0].message.content :
                        null;

                    if (!isNonEmpty(reply)) {
                        const err = new Error("A chat API válasz nem tartalmaz feldolgozható szöveget.");
                        err.payload = payload;
                        throw err;
                    }

                    doc.messages.push({ id: uid(), type: "text", role: "assistant", content: reply, createdAt: nowIso() });
                    if (payload && payload.title) doc.title = String(payload.title);
                    await model.saveConversation(doc);
                    els.chatTitle.textContent = doc.title || "tiffytime";
                    await render.renderConversation(doc);
                    await app.renderRecent();
                },
                async sendDeepResearch(text, doc) {
                    const query = String(text || "").trim();
                    if (!query) {
                        const err = new Error("Deep Research módban küldéshez szükséges kérdés szöveg.");
                        throw err;
                    }

                    const planResp = await deepResearch.createPlan(doc, query);
                    if (planResp.title) doc.title = planResp.title;

                    const planMsg = {
                        id: uid(),
                        type: "dr_plan",
                        createdAt: nowIso(),
                        query,
                        sources: [...state.ui.sources],
                        planId: planResp.planId,
                        title: planResp.title || doc.title || "tiffytime",
                        plan: planResp.plan
                    };
                    doc.messages.push(planMsg);
                    await model.saveConversation(doc);
                    els.chatTitle.textContent = doc.title || "tiffytime";
                    await render.renderConversation(doc);
                    await app.renderRecent();
                },
                async openPlanEditor(messageId) {
                    const doc = await model.loadConversation(state.currentConversationId);
                    if (!doc) return;
                    const msg = doc.messages.find(m => m && m.id === messageId);
                    if (!msg || msg.type !== "dr_plan") return;
                    planEditor.open(msg);
                },
                async savePlanEdits() {
                    const messageId = state.planEditor.messageId;
                    if (!messageId) {
                        planEditor.close();
                        return;
                    }
                    const doc = await model.loadConversation(state.currentConversationId);
                    if (!doc) {
                        planEditor.close();
                        return;
                    }
                    const idx = doc.messages.findIndex(m => m && m.id === messageId);
                    if (idx < 0) {
                        planEditor.close();
                        return;
                    }
                    const msg = doc.messages[idx];
                    if (!msg || msg.type !== "dr_plan") {
                        planEditor.close();
                        return;
                    }
                    const draft = Array.isArray(state.planEditor.draft) ? state.planEditor.draft.map(s => String(s || "").trim()).filter(s => s.length) : [];
                    if (!draft.length) return;
                    msg.plan = draft;
                    await model.saveConversation(doc);
                    planEditor.close();
                    await render.renderConversation(doc);
                    await app.renderRecent();
                },
                async startResearch(messageId) {
                    if (state.pending) return;
                    render.setPending(true);
                    try {
                        const doc = await model.loadConversation(state.currentConversationId);
                        if (!doc) return;
                        const msg = doc.messages.find(m => m && m.id === messageId);
                        if (!msg || msg.type !== "dr_plan") return;

                        const start = await deepResearch.startRun(doc, msg);
                        const progressMsgId = uid();

                        const progressMsg = {
                            id: progressMsgId,
                            type: "dr_progress",
                            createdAt: nowIso(),
                            runId: start.runId,
                            title: start.title,
                            progress: 0,
                            stream: []
                        };

                        doc.messages.push(progressMsg);
                        doc.runs = doc.runs || {};
                        doc.runs[start.runId] = {
                            status: "running",
                            title: start.title,
                            planId: msg.planId,
                            query: msg.query,
                            sources: msg.sources,
                            updatedAt: nowIso()
                        };

                        await model.saveConversation(doc);
                        await render.renderConversation(doc);
                        await app.renderRecent();

                        render.setPending(false);

                        deepResearch.startMonitoring(doc, start.runId, progressMsgId);
                    } catch (e) {
                        const doc = await model.loadConversation(state.currentConversationId);
                        if (doc) {
                            doc.messages.push({ id: uid(), type: "dr_error", createdAt: nowIso(), error: (e && e.message) ? e.message : "Ismeretlen hiba" });
                            await model.saveConversation(doc);
                            await render.renderConversation(doc);
                        }
                    } finally {
                        render.setPending(false);
                    }
                },
                async openReport(runId) {
                    const doc = await model.loadConversation(state.currentConversationId);
                    if (!doc) return;
                    const report = await deepResearch.fetchReport(doc.id, runId);
                    doc.runs = doc.runs || {};
                    doc.runs[runId] = doc.runs[runId] || {};
                    doc.runs[runId].report = report;
                    doc.runs[runId].status = "ready";
                    doc.runs[runId].updatedAt = nowIso();
                    await model.saveConversation(doc);
                    reportView.show(report);
                },
                async openReportSources(runId) {
                    const doc = await model.loadConversation(state.currentConversationId);
                    if (!doc) return;
                    const run = doc.runs && doc.runs[runId] ? doc.runs[runId] : null;
                    const sources = run && run.report && Array.isArray(run.report.sources) ? run.report.sources : null;
                    if (sources) {
                        reportView.openSourcesPanel(sources);
                        return;
                    }
                    const report = await deepResearch.fetchReport(doc.id, runId);
                    doc.runs = doc.runs || {};
                    doc.runs[runId] = doc.runs[runId] || {};
                    doc.runs[runId].report = report;
                    doc.runs[runId].status = "ready";
                    doc.runs[runId].updatedAt = nowIso();
                    await model.saveConversation(doc);
                    reportView.openSourcesPanel(report.sources);
                }
            };

            app.boot().catch(() => {});
        })();
    </script>
</body>
</html>
